// One request per board. Add an ATS here and in "Normalise and match" to support more.
const cfg = $input.first().json;
const url = {
  ashby:      s => 'https://api.ashbyhq.com/posting-api/job-board/' + s,
  greenhouse: s => 'https://boards-api.greenhouse.io/v1/boards/' + s + '/jobs',
  lever:      s => 'https://api.lever.co/v0/postings/' + s + '?mode=json',
  recruitee:  s => 'https://' + s + '.recruitee.com/api/offers/'
};
const boards = Array.isArray(cfg.boards) ? cfg.boards : [];
const unknown = boards.filter(b => !url[b.ats]).map(b => b.ats);
if (unknown.length) console.log('unsupported ats, skipped: ' + unknown.join(', '));
return boards.filter(b => url[b.ats] && b.slug).map(b => ({ json: { ats: b.ats, slug: b.slug, url: url[b.ats](b.slug) } }));

// One input item per board, in the same order as the requests, because the HTTP node
// was told to return text: an array response would otherwise be split into many items.
const cfg = $('Boards and filters').first().json;
const reqs = $('Build board requests').all().map(i => i.json);
const lower = (v) => String(v ?? '').toLowerCase();
// Words of up to three letters match whole words only, so "ai" does not hit "Retail"
// and "eu" does not hit "Seoul". Longer words and phrases match anywhere in the text.
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (hay, w) => {
  const word = lower(w).trim();
  if (!word) return false;
  if (word.length > 3) return hay.includes(word);
  return new RegExp('(^|[^a-z0-9])' + esc(word) + '($|[^a-z0-9])').test(hay);
};
const any = (hay, list) => !list || !list.length || list.some(w => has(hay, w));
const none = (hay, list) => !list || !list.length || !list.some(w => has(hay, w));

function parse(ats, body) {
  let d;
  try { d = typeof body === 'string' ? JSON.parse(body) : body; } catch (e) { return []; }
  if (!d) return [];
  if (ats === 'ashby') return (d.jobs || []).map(j => ({
    ref: j.jobId || j.id, title: j.title, company: j.organizationName || '',
    location: [j.location, ...(j.secondaryLocations || []).map(l => l.location)].filter(Boolean).join(' / '),
    remote: !!j.isRemote, url: j.jobUrl, posted: j.publishedAt }));
  if (ats === 'greenhouse') return (d.jobs || []).map(j => ({
    ref: j.id, title: j.title, company: '', location: (j.location || {}).name || '',
    remote: /remote/i.test(((j.location || {}).name) || ''), url: j.absolute_url, posted: j.updated_at }));
  if (ats === 'lever') return (Array.isArray(d) ? d : []).map(j => ({
    ref: j.id, title: j.text, company: '', location: (j.categories || {}).location || '',
    remote: /remote/i.test(j.workplaceType || (j.categories || {}).location || ''),
    url: j.hostedUrl, posted: j.createdAt ? new Date(j.createdAt).toISOString() : '' }));
  if (ats === 'recruitee') return (d.offers || []).map(j => ({
    ref: j.id, title: j.title, company: j.company_name || '',
    location: [j.city, j.country].filter(Boolean).join(', '), remote: !!j.remote,
    url: j.careers_url || j.careers_apply_url, posted: j.published_at || j.created_at }));
  return [];
}

const out = [];
$input.all().forEach((item, i) => {
  const req = reqs[i] || {};
  if (item.json.error) { console.log('board failed: ' + req.slug + ' (' + req.ats + ')'); return; }
  for (const r of parse(req.ats, item.json.data)) {
    const title = lower(r.title), loc = lower(r.location);
    if (!any(title, cfg.title_any) || !none(title, cfg.title_none)) continue;
    // The remote flag alone is not trusted: some boards set it on office roles. The location
    // text decides; only a remote posting with no location text passes on the flag alone.
    const locOk = (loc || !r.remote) ? any(loc, cfg.location_any) : true;
    if (!locOk || !none(loc, cfg.location_none)) continue;
    out.push({ json: {
      id: req.ats + ':' + req.slug + ':' + r.ref,
      title: r.title, company: r.company || req.slug, ats: req.ats,
      location: r.location || (r.remote ? 'remote' : ''), remote: r.remote,
      url: r.url, posted: String(r.posted || '').slice(0, 10),
      found_at: new Date().toISOString().slice(0, 10) } });
  }
});
return out;

// One message instead of one per role. Remove this node if you want them separately.
const rows = $input.all().map(i => i.json);
if (!rows.length) return [];
const lines = rows.slice(0, 20).map(r =>
  '• *' + r.title + '* — ' + (r.company || r.ats) + (r.location ? ' · ' + r.location : '') + (r.posted ? ' · ' + r.posted : '') + '\n  ' + r.url);
return [{ json: {
  count: rows.length,
  text: ':mag: *' + rows.length + ' new role' + (rows.length === 1 ? '' : 's') + '* on the boards you watch\n\n'
        + lines.join('\n') + (rows.length > 20 ? '\n\n…and ' + (rows.length - 20) + ' more' : '')
} }];
